// MakeDay, for the parser's years, months 0–11, and days.
fn make_day(year: i32, month: i32, date: i32) -> Option<f64> {
    if !(-1_000_000..=1_000_000).contains(&year) {
        return None;
    }
    let y = i64::from(year);
    const YEAR_DELTA: i64 = 399_999;
    let days = |y: i64| {
        let y = y + YEAR_DELTA;
        365 * y + y / 4 - y / 100 + y / 400
    };
    let leap = y % 4 == 0 && (y % 100 != 0 || y % 400 == 0);
    const COMMON: [i64; 12] = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
    const LEAP: [i64; 12] = [0, 31, 60, 91, 121, 152, 182, 213, 244, 274, 305, 335];
    let from_month = if leap { LEAP } else { COMMON }[month as usize];
    Some((days(y) - days(1970) + from_month - 1) as f64 + f64::from(date))
}

