// A word longer than its keyword matches only a month name.
fn keyword(prefix: [u32; 3], len: i32) -> (Kind, i32) {
    KEYWORDS
        .iter()
        .find(|(word, kind, _)| {
            word.iter().zip(prefix).all(|(&w, p)| u32::from(w) == p)
                && (len <= 3 || *kind == Kind::MonthName)
        })
        .map_or((Kind::Invalid, 0), |&(_, kind, value)| (kind, value))
}

struct Scanner<'a> {
    input: Reader<'a>,
    next: Token,
}

impl Scanner<'_> {
    fn next(&mut self) -> Token {
        let result = self.next;
        self.next = self.scan();
        result
    }

    fn peek(&self) -> Token {
        self.next
    }

    fn skip_symbol(&mut self, c: u8) -> bool {
        if self.next.is_symbol(c) {
            self.next = self.scan();
            return true;
        }
        false
    }

    fn scan(&mut self) -> Token {
        let input = &mut self.input;
        let start = input.index;
        if input.ch == 0 {
            return Token::End;
        }
        if input.is_digit() {
            let value = input.read_unsigned_numeral();
            let length = (input.index - start) as i32;
            return Token::Number { value, length };
        }
        for c in [b':', b'-', b'+', b'.', b')'] {
            if input.skip(c) {
                return Token::Symbol(c);
            }
        }
        if input.is_alpha_or_above() && !is_white_space(input.ch) {
            let (prefix, length) = input.read_word();
            let (kind, value) = keyword(prefix, length);
            return Token::Keyword {
                kind,
                value,
                length,
            };
        }
        if input.skip_white_space() {
            return Token::WhiteSpace;
        }
        if input.skip_parentheses() {
            return Token::Unknown;
        }
        input.next();
        Token::Unknown
    }
}

struct TimeZone {
    sign: i32,
    hour: i32,
    minute: i32,
}

impl TimeZone {
    fn set(&mut self, offset_in_hours: i32) {
        self.sign = if offset_in_hours < 0 { -1 } else { 1 };
        self.hour = offset_in_hours * self.sign;
        self.minute = 0;
    }
    fn set_sign(&mut self, sign: i32) {
        self.sign = if sign < 0 { -1 } else { 1 };
    }
    fn is_expecting(&self, n: i32) -> bool {
        self.hour != NONE && self.minute == NONE && between(n, 0, 59)
    }
    fn is_utc(&self) -> bool {
        self.hour == 0 && self.minute == 0
    }
    fn is_empty(&self) -> bool {
        self.hour == NONE
    }
    fn write(&mut self) -> Option<Option<i32>> {
        if self.sign == NONE {
            return Some(None);
        }
        if self.hour == NONE {
            self.hour = 0;
        }
        if self.minute == NONE {
            self.minute = 0;
        }
        // Unsigned arithmetic, as V8's, wrapping where it would.
        let total = (self.hour as u32)
            .wrapping_mul(3600)
            .wrapping_add((self.minute as u32).wrapping_mul(60));
        if total > SMI_MAX {
            return None;
        }
        let total = total as i32;
        Some(Some(if self.sign < 0 { -total } else { total }))
    }
}

struct Time {
    comp: [i32; 4],
    index: usize,
    hour_offset: i32,
}

impl Time {
    fn is_empty(&self) -> bool {
        self.index == 0
    }
    fn is_expecting(&self, n: i32) -> bool {
        (self.index == 1 && between(n, 0, 59))
            || (self.index == 2 && between(n, 0, 59))
            || (self.index == 3 && between(n, 0, 999))
    }
    fn add(&mut self, n: i32) -> bool {
        if self.index < 4 {
            self.comp[self.index] = n;
            self.index += 1;
            return true;
        }
        false
    }
    fn add_final(&mut self, n: i32) -> bool {
        if !self.add(n) {
            return false;
        }
        while self.index < 4 {
            self.comp[self.index] = 0;
            self.index += 1;
        }
        true
    }
    fn write(&mut self, out: &mut Output) -> bool {
        while self.index < 4 {
            self.comp[self.index] = 0;
            self.index += 1;
        }
        let [mut hour, minute, second, millisecond] = self.comp;
        if self.hour_offset != NONE {
            if !between(hour, 0, 12) {
                return false;
            }
            hour %= 12;
            hour += self.hour_offset;
        }
        if !between(hour, 0, 23)
            || !between(minute, 0, 59)
            || !between(second, 0, 59)
            || !between(millisecond, 0, 999)
        {
            // A 24th hour is allowed if minutes, seconds, and milliseconds are 0.
            if hour != 24 || minute != 0 || second != 0 || millisecond != 0 {
                return false;
            }
        }
        out.hour = i64::from(hour);
        out.minute = i64::from(minute);
        out.second = i64::from(second);
        out.millisecond = i64::from(millisecond);
        true
    }
}

struct Day {
    comp: [i32; 3],
    index: usize,
    named_month: i32,
    is_iso_date: bool,
}

impl Day {
    fn is_empty(&self) -> bool {
        self.index == 0
    }
    fn add(&mut self, n: i32) -> bool {
        if self.index < 3 {
            self.comp[self.index] = n;
            self.index += 1;
            return true;
        }
        false
    }
    fn write(&mut self, out: &mut Output) -> bool {
        if self.index < 1 {
            return false;
        }
        // Day and month default to 1.
        while self.index < 3 {
            self.comp[self.index] = 1;
            self.index += 1;
        }
        let is_day = |x: i32| between(x, 1, 31);
        let c = self.comp;
        // The default year 0 becomes 2000, for KJS compatibility.
        let (mut year, month, day);
        if self.named_month == NONE {
            if self.is_iso_date || (self.index == 3 && !is_day(c[0])) {
                (year, month, day) = (c[0], c[1], c[2]);
            } else {
                (year, month, day) = (if self.index == 3 { c[2] } else { 0 }, c[0], c[1]);
            }
        } else {
            month = self.named_month;
            if self.index == 1 {
                (year, day) = (0, c[0]);
            } else if !is_day(c[0]) {
                (year, day) = (c[0], c[1]);
            } else {
                (year, day) = (c[1], c[0]);
            }
        }
        if !self.is_iso_date {
            if between(year, 0, 49) {
                year += 2000;
            } else if between(year, 50, 99) {
                year += 1900;
            }
        }
        if !between(month, 1, 12) || !is_day(day) {
            return false;
        }
        out.year = year;
        out.month = month - 1;
        out.day = day;
        true
    }
}

// Milliseconds from a numeral's first three significant digits, the numeral's length telling
// its leading zeros.
fn read_milliseconds(token: Token) -> i32 {
    let Token::Number { value, length } = token else {
        unreachable!("a number token")
    };
    match length {
        1 => value * 100,
        2 => value * 10,
        3 => value,
        _ => {
            let mut length = length.min(MAX_SIGNIFICANT_DIGITS);
            let mut factor = 1;
            while length > 3 {
                factor *= 10;
                length -= 1;
            }
            value / factor
        }
    }
}

fn parse(units: &[u16]) -> Option<Output> {
    let mut input = Reader {
        buffer: units,
        index: 0,
        ch: 0,
    };
    input.next();
    let mut scanner = Scanner {
        input,
        next: Token::End,
    };
    scanner.next = scanner.scan();
    let mut tz = TimeZone {
        sign: NONE,
        hour: NONE,
        minute: NONE,
    };
    let mut time = Time {
        comp: [0; 4],
        index: 0,
        hour_offset: NONE,
    };
    let mut day = Day {
        comp: [0; 3],
        index: 0,
        named_month: NONE,
        is_iso_date: false,
    };

    // As far as possible as an ES5 date-time string; the legacy parser takes the rest.
    let unhandled = parse_es5(&mut scanner, &mut day, &mut time, &mut tz);
    if matches!(unhandled, Token::Invalid) {
        return None;
    }
    let mut has_read_number = !day.is_empty();
    let mut token = unhandled;
    while !matches!(token, Token::End) {
        if let Token::Number { value: n, .. } = token {
            has_read_number = true;
            if scanner.skip_symbol(b':') {
                if scanner.skip_symbol(b':') {
                    // n + "::"
                    if !time.is_empty() {
                        return None;
                    }
                    time.add(n);
                    time.add(0);
                } else {
                    // n + ":"
                    if !time.add(n) {
                        return None;
                    }
                    if scanner.peek().is_symbol(b'.') {
                        scanner.next();
                    }
                }
            } else if scanner.skip_symbol(b'.') && time.is_expecting(n) {
                time.add(n);
                if !scanner.peek().is_number() {
                    return None;
                }
                let ms = read_milliseconds(scanner.next());
                if ms < 0 {
                    return None;
                }
                time.add_final(ms);
            } else if tz.is_expecting(n) {
                tz.minute = n;
            } else if time.is_expecting(n) {
                time.add_final(n);
                // End, white space, "Z", "+", or "-" must follow a finished time.
                let peek = scanner.peek();
                if !matches!(peek, Token::End | Token::WhiteSpace)
                    && !peek.is_keyword_z()
                    && !peek.is_sign()
                {
                    return None;
                }
            } else {
                if !day.add(n) {
                    return None;
                }
                scanner.skip_symbol(b'-');
            }
        } else if let Token::Keyword { kind, value, .. } = token {
            if kind == Kind::AmPm && !time.is_empty() {
                time.hour_offset = value;
            } else if kind == Kind::MonthName {
                day.named_month = value;
                scanner.skip_symbol(b'-');
            } else if kind == Kind::TimeZoneName && has_read_number {
                tz.set(value);
            } else {
                // Garbage words are illegal once a number has been read, and must be
                // separated from the first number.
                if has_read_number || scanner.peek().is_number() {
                    return None;
                }
            }
        } else if token.is_sign() && (tz.is_utc() || !time.is_empty()) {
            // A UTC offset, only after UTC or a time.
            tz.set_sign(token.sign());
            let (mut n, mut length) = (0, 0);
            if scanner.peek().is_number() {
                if let Token::Number { value, length: l } = scanner.next() {
                    (n, length) = (value, l);
                }
            }
            has_read_number = true;
            if scanner.peek().is_symbol(b':') {
                tz.hour = n;
                tz.minute = NONE;
            } else if length == 1 || length == 2 {
                // GMT-8
                tz.hour = n;
                tz.minute = 0;
            } else if length == 3 || length == 4 {
                // hhmm
                tz.hour = n / 100;
                tz.minute = n % 100;
            } else {
                return None;
            }
        } else if (token.is_sign() || token.is_symbol(b')')) && has_read_number {
            // An extra sign or ')' is illegal once a number has been read.
            return None;
        }
        // Other characters and white space are ignored.
        token = scanner.next();
    }

    let mut out = Output {
        year: 0,
        month: 0,
        day: 0,
        hour: 0,
        minute: 0,
        second: 0,
        millisecond: 0,
        utc_offset: None,
    };
    if !day.write(&mut out) || !time.write(&mut out) {
        return None;
    }
    out.utc_offset = tz.write()?;
    Some(out)
}

// [('-'|'+')yy]yyyy[-MM[-DD]][THH:mm[:ss[.sss]][Z|(+|-)hh:mm]]. Returns the token the legacy
// parser continues with: End when the string is complete, Invalid when it can't be a date.
fn parse_es5(
    scanner: &mut Scanner<'_>,
    day: &mut Day,
    time: &mut Time,
    tz: &mut TimeZone,
) -> Token {
    if scanner.peek().is_sign() {
        // The sign goes back to the legacy parser if no six-digit year follows.
        let sign_token = scanner.next();
        if !scanner.peek().is_fixed_length_number(6) {
            return sign_token;
        }
        let sign = sign_token.sign();
        let year = scanner.next().number();
        if sign < 0 && year == 0 {
            return sign_token;
        }
        day.add(sign * year);
    } else if scanner.peek().is_fixed_length_number(4) {
        day.add(scanner.next().number());
    } else {
        return scanner.next();
    }
    if scanner.skip_symbol(b'-') {
        if !scanner.peek().is_fixed_length_number(2) || !between(scanner.peek().number(), 1, 12) {
            return scanner.next();
        }
        day.add(scanner.next().number());
        if scanner.skip_symbol(b'-') {
            if !scanner.peek().is_fixed_length_number(2) || !between(scanner.peek().number(), 1, 31)
            {
                return scanner.next();
            }
            day.add(scanner.next().number());
        }
    }
    if !scanner.peek().is_keyword(Kind::TimeSeparator) {
        if !matches!(scanner.peek(), Token::End) {
            return scanner.next();
        }
    } else {
        scanner.next();
        if !scanner.peek().is_fixed_length_number(2) || !between(scanner.peek().number(), 0, 24) {
            return Token::Invalid;
        }
        // 24:00[:00[.000]], but no other time in hour 24.
        let hour_is_24 = scanner.peek().number() == 24;
        time.add(scanner.next().number());
        if !scanner.skip_symbol(b':') {
            return Token::Invalid;
        }
        if !scanner.peek().is_fixed_length_number(2)
            || !between(scanner.peek().number(), 0, 59)
            || (hour_is_24 && scanner.peek().number() > 0)
        {
            return Token::Invalid;
        }
        time.add(scanner.next().number());
        if scanner.skip_symbol(b':') {
            if !scanner.peek().is_fixed_length_number(2)
                || !between(scanner.peek().number(), 0, 59)
                || (hour_is_24 && scanner.peek().number() > 0)
            {
                return Token::Invalid;
            }
            time.add(scanner.next().number());
            if scanner.skip_symbol(b'.') {
                if !scanner.peek().is_number() || (hour_is_24 && scanner.peek().number() > 0) {
                    return Token::Invalid;
                }
                // More or fewer than three digits are allowed.
                time.add(read_milliseconds(scanner.next()));
            }
        }
        if scanner.peek().is_keyword_z() {
            scanner.next();
            tz.set(0);
        } else if scanner.peek().is_sign() {
            tz.set_sign(scanner.next().sign());
            if scanner.peek().is_fixed_length_number(4) {
                // hhmm
                let hourmin = scanner.next().number();
                let (hour, min) = (hourmin / 100, hourmin % 100);
                if !between(hour, 0, 23) || !between(min, 0, 59) {
                    return Token::Invalid;
                }
                tz.hour = hour;
                tz.minute = min;
            } else {
                // hh:mm
                if !scanner.peek().is_fixed_length_number(2)
                    || !between(scanner.peek().number(), 0, 23)
                {
                    return Token::Invalid;
                }
                tz.hour = scanner.next().number();
                if !scanner.skip_symbol(b':') {
                    return Token::Invalid;
                }
                if !scanner.peek().is_fixed_length_number(2)
                    || !between(scanner.peek().number(), 0, 59)
                {
                    return Token::Invalid;
                }
                tz.minute = scanner.next().number();
            }
        }
        if !matches!(scanner.peek(), Token::End) {
            return Token::Invalid;
        }
    }
    // Date-only forms are UTC; date-time forms without a zone are local.
    if tz.is_empty() && time.is_empty() {
        tz.set(0);
    }
    day.is_iso_date = true;
    Token::End
}
